using System;
using EmberBastion;
class R12Checks {
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);}
 static void Main(){var seed=new Battle(42,0);var oldPrep=seed.SavePreparation();oldPrep.rulesVersion=1;var fresh=Battle.RestorePreparation(oldPrep);fresh.Place(0,0);fresh.Start();var first=fresh.Field.Waves[0][0];Check(fresh.RulesVersion==1&&fresh.Pending==fresh.SpawnCount(first),"new density at start");Check(fresh.SpawnCount(first)==(int)Math.Round(first.Count*1.25),"scaled count");var data=fresh.ExportCombat();var same=Battle.ImportCombat(data);Check(same.RulesVersion==1&&same.Pending==fresh.Pending,"new save round trip");var legacy=fresh.ExportCombat();legacy.rulesVersion=0;var old=Battle.ImportCombat(legacy);Check(old.RulesVersion==0&&old.SpawnCount(first)==first.Count,"legacy waves unchanged");Check(old.CopyCombat().RulesVersion==0,"legacy checkpoint retains rules");var hard=new Battle(42,0);hard.SetDifficulty(2);Check(hard.SpawnCount(first)==first.Count&&hard.SpawnGap(first)==first.Gap,"hard unchanged");Check(BadgeRules.Limit(0,false,false)==41&&BadgeRules.Limit(0,false,false,true)==35,"new and old badge thresholds");Console.WriteLine("PASS r12 density, legacy save, retry, hard mode and badge versions");}
}
